// Converts the Tabler SVGs in third_party/tabler-icons/ into Compose ImageVectors.
// Run from the project root:  node third_party/gen-tabler-icons.js
// Output: app/src/main/java/com/driftwood/browser/ui/icons/Tabler.kt
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const svgDir = path.join(__dirname, "tabler-icons");
const out = path.join(root, "app/src/main/java/com/driftwood/browser/ui/icons/Tabler.kt");

const pascal = (name) =>
  name.split("-").map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join("");

const icons = fs
  .readdirSync(svgDir)
  .filter((f) => f.endsWith(".svg"))
  .sort()
  .map((f) => {
    const svg = fs.readFileSync(path.join(svgDir, f), "utf8");
    const paths = [...svg.matchAll(/<path\s+d="([^"]+)"/g)].map((m) => m[1]);
    if (paths.length === 0) throw new Error(`No paths in ${f}`);
    return { name: pascal(f.replace(".svg", "")), paths };
  });

let kt = `// GENERATED by third_party/gen-tabler-icons.js from Tabler Icons (MIT licence,
// see third_party/TABLER_LICENSE.txt). Do not edit by hand.
package com.driftwood.browser.ui.icons

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

object Tabler {
`;
for (const icon of icons) {
  kt += `    val ${icon.name}: ImageVector by lazy {\n        tablerIcon(\n            "${icon.name}",\n`;
  for (const d of icon.paths) kt += `            "${d}",\n`;
  kt += `        )\n    }\n`;
}
kt += `}

private fun tablerIcon(name: String, vararg paths: String): ImageVector {
    val builder = ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
    )
    for (d in paths) {
        builder.addPath(
            pathData = addPathNodes(d),
            stroke = SolidColor(Color.Black),
            strokeLineWidth = 2f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        )
    }
    return builder.build()
}
`;
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, kt);
console.log(`Wrote ${icons.length} icons: ${icons.map((i) => i.name).join(", ")}`);
